// The SF Symbol names of the original stay the keys (IconCatalog.g.cs, generated by tools/icons.py), so a view reads
// side by side with its Swift: systemImage: "lasso" becomes <c:Icon Symbol="lasso"/>.
using System.Windows.Media;

namespace Glimmer.App.Icons;

public enum IconKind { Glyph, Path, Text }

/// <summary>How one icon is drawn: a glyph of the icon font, a path in a 16 × 16 box, or text in the interface font.</summary>
public sealed class IconSpec
{
    private Geometry? stroke, fill;
    private bool parsed;

    private IconSpec(IconKind kind) => Kind = kind;

    public IconKind Kind { get; }
    public char Glyph { get; private init; }
    public bool Mirror { get; private init; }
    public string? StrokeData { get; private init; }
    public string? FillData { get; private init; }
    public bool EvenOdd { get; private init; }
    public string? Text { get; private init; }
    public bool Italic { get; private init; }

    public static IconSpec FromGlyph(char glyph, bool mirror) => new(IconKind.Glyph) { Glyph = glyph, Mirror = mirror };
    public static IconSpec FromPath(string? stroke, string? fill, bool evenOdd) => new(IconKind.Path) { StrokeData = stroke, FillData = fill, EvenOdd = evenOdd };
    public static IconSpec FromText(string text, bool italic) => new(IconKind.Text) { Text = text, Italic = italic };

    /// <summary>The stroked part, in the 16 × 16 box (frozen).</summary>
    public Geometry? Stroke { get { Parse(); return stroke; } }
    /// <summary>The filled part, in the 16 × 16 box (frozen).</summary>
    public Geometry? Fill { get { Parse(); return fill; } }

    private void Parse()
    {
        if (parsed) return;
        parsed = true;
        if (StrokeData is not null) stroke = Freeze(Geometry.Parse(StrokeData));
        if (FillData is not null) fill = Freeze(Geometry.Parse((EvenOdd ? "F0 " : "F1 ") + FillData));
    }

    private static Geometry Freeze(Geometry g)
    {
        if (g.CanFreeze) g.Freeze();
        return g;
    }
}

public static partial class IconCatalog
{
    /// <summary>Segoe Fluent Icons on Windows 11; Windows 10 has the same code points in Segoe MDL2 Assets, and WPF
    /// falls back per glyph along the list.</summary>
    public static readonly FontFamily IconFont = new("Segoe Fluent Icons, Segoe MDL2 Assets");

    public static IconSpec? Resolve(string? sfSymbol) =>
        sfSymbol is not null && BySfSymbol.TryGetValue(sfSymbol, out var spec) ? spec : null;
}
